function Assert-HeldDescriptor($Stream,$Row){
 $m=[VerifyInstallFiles]::Metadata($Stream.SafeFileHandle)
 if(($m.Attributes -band 0x410) -ne 0 -or $m.Links -ne 1 -or $m.SizeHigh -ne 0 -or $m.SizeLow -ne $Row.bytes -or $m.Volume -ne $Row.volume -or $m.IndexHigh -ne $Row.indexHigh -or $m.IndexLow -ne $Row.indexLow){throw 'ACTUAL_PREDECESSOR_FILE_ID_REQUIRED'}
 $actual=[Convert]::ToBase64String([VerifyInstallFiles]::Security($Stream.SafeFileHandle));if($actual -cne $Row.securityDescriptorBase64){throw 'ACTUAL_SAME_HANDLE_DESCRIPTOR_REQUIRED'}
}
function Read-HeldPublic($Stream,[string]$Expected){
 if($Stream.Length -lt 1 -or $Stream.Length -gt 16MB){throw 'PUBLIC_SIZE_REFUSED'};$Stream.Position=0;$b=New-Object byte[] ([int]$Stream.Length);$at=0;while($at -lt $b.Length){$n=$Stream.Read($b,$at,$b.Length-$at);if($n -lt 1){throw 'PUBLIC_TRUNCATED'};$at+=$n};if((Public-Hash $b) -cne $Expected){throw 'PUBLIC_BYTES_CHANGED'};$Stream.Position=0;return ,$b
}
function Hold-ExistingPublic([string]$Relative,[string]$Expected,[switch]$SwapDelete){
 $path=Join-Path $Root ($Relative.Replace('/','\'));$parts=New-Object 'Collections.Generic.List[string]';for($p=Split-Path -Parent $path;$p -cne $Root;$p=Split-Path -Parent $p){$parts.Insert(0,$p)};foreach($p in $parts){Hold-Directory $p 'Public'}
 $share=[IO.FileShare]::Read;if($SwapDelete){$share=$share -bor [IO.FileShare]::Delete};$s=[IO.File]::Open($path,'Open','Read',$share);$keep=$false
 try{[VerifyInstallFiles]::ExactPath($s.SafeFileHandle,$path);$m=[VerifyInstallFiles]::Metadata($s.SafeFileHandle);if(($m.Attributes -band 0x410) -ne 0 -or $m.Links -ne 1){throw 'PUBLIC_TYPE_LINK_REFUSED'};$a=New-Object Security.AccessControl.FileSecurity;$a.SetSecurityDescriptorBinaryForm([VerifyInstallFiles]::Security($s.SafeFileHandle));Assert-ExactAcl $a $false 'Public';$null=Read-HeldPublic $s $Expected;$held.Add($s);$keep=$true;return $s}finally{if(-not $keep){$s.Dispose()}}
}

function Capture-PublicRow($Stream,$Expected){
