 if($n.tree_cleanup_confirmed -ne $true -or $n.root_exit_confirmed -ne $true -or $n.tree_active_processes -ne 0 -or $null -ne $n.tree_cleanup_failure_code){throw 'FORMAL_TREE_CLEANUP_UNCONFIRMED'}
 $receipt.tree_cleanup_confirmed=$true;$receipt.root_exit_confirmed=$true;$receipt.tree_active_processes=0;$receipt.native_receipt_sha256=Public-Hash $bytes
 if($n.state -cne 'FIXED_CHILD_COMPLETED' -or $null -ne $n.failure_code -or $n.node_exit_code -ne 0 -or $n.timed_out -ne $false -or $n.stop_requested -ne $false){throw 'FORMAL_CHILD_REFUSED_OR_UNKNOWN'}
 $receipt.formal_child_completed=$true
}
